static float clip(float value, float lower, float upper)
{
    if (value < lower) return lower;
    if (value > upper) return upper;
    return value;
}

static float elu(float value)
{
    return value >= 0.0f ? value : expf(value) - 1.0f;
}

static void linear_elu(
    const float *input, size_t input_size, float *output, size_t output_size,
    const float *weight, const float *bias)
{
    size_t row;
    size_t column;
    for (row = 0; row < output_size; ++row) {
        float sum = bias[row];
        const float *row_weight = weight + row * input_size;
        for (column = 0; column < input_size; ++column) {
            sum += row_weight[column] * input[column];
        }
        output[row] = elu(sum);
    }
}

void g1_assist_v4_history_reset(
    G1AssistV4History *history,
    const float initial_position_rad[2],
    const float initial_velocity_rad_s[2])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || initial_position_rad == NULL || initial_velocity_rad_s == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V4_HISTORY_LENGTH; ++frame) {
        for (side = 0; side < 2; ++side) {
            history->position_rad[frame][side] = initial_position_rad[side];
            history->velocity_rad_s[frame][side] = initial_velocity_rad_s[side];
            history->smoothed_torque_nm[frame][side] = 0.0f;
        }
    }
    for (frame = 0; frame < 25; ++frame)
        for (side = 0; side < 10; ++side) history->pulse_state[frame][side] = 0.0f;
    history->next_index = 0U;
}

void g1_assist_v4_history_append(
    G1AssistV4History *history,
    const float position_rad[2],
    const float velocity_rad_s[2],
    const float previous_smoothed_torque_nm[2], const float pulse_state[10])
{
    unsigned int side;
    unsigned int index;
    if (history == NULL || position_rad == NULL || velocity_rad_s == NULL || previous_smoothed_torque_nm == NULL) return;
    index = history->next_index;
    for (side = 0; side < 2; ++side) {
        history->position_rad[index][side] = position_rad[side];
        history->velocity_rad_s[index][side] = velocity_rad_s[side];
        history->smoothed_torque_nm[index][side] = previous_smoothed_torque_nm[side];
    }
    for (side = 0; side < 10; ++side) history->pulse_state[index][side] = pulse_state[side];
    history->next_index = (index + 1U) % G1_ASSIST_V4_HISTORY_LENGTH;
}

void g1_assist_v4_history_build_observation(
    const G1AssistV4History *history,
    float observation[G1_ASSIST_V4_INPUT_SIZE])
{
    unsigned int frame;
    unsigned int side;
    if (history == NULL || observation == NULL) return;
    for (frame = 0; frame < G1_ASSIST_V4_HISTORY_LENGTH; ++frame) {
        unsigned int source = (history->next_index + frame) % G1_ASSIST_V4_HISTORY_LENGTH;
        for (side = 0; side < 2; ++side) {
            observation[frame * 2U + side] = history->position_rad[source][side];
            observation[50U + frame * 2U + side] = history->velocity_rad_s[source][side];
            observation[100U + frame * 2U + side] = history->smoothed_torque_nm[source][side];
        }
        for (side = 0; side < 10; ++side) observation[150U + frame * 10U + side] = history->pulse_state[source][side];
    }
}

void g1_assist_v4_policy_forward(
    const float observation[G1_ASSIST_V4_INPUT_SIZE],
    float action[G1_ASSIST_V4_OUTPUT_SIZE],
    G1AssistV4Workspace *workspace)
{
    size_t index;
    size_t row;
    size_t column;
    if (observation == NULL || action == NULL || workspace == NULL) return;
    for (index = 0; index < G1_ASSIST_V4_INPUT_SIZE; ++index) {
        workspace->secondary_400[index] =
            (observation[index] - OBS_MEAN[index]) / (OBS_STD[index] + NORMALIZER_EPS);
    }
    linear_elu(workspace->secondary_400, 400, workspace->hidden_256, 256, WEIGHT_0, BIAS_0);
    linear_elu(workspace->hidden_256, 256, workspace->secondary_400, 64, WEIGHT_1, BIAS_1);
    linear_elu(workspace->secondary_400, 64, workspace->hidden_256, 16, WEIGHT_2, BIAS_2);
    for (row = 0; row < G1_ASSIST_V4_OUTPUT_SIZE; ++row) {
        float sum = BIAS_3[row];
        const float *row_weight = WEIGHT_3 + row * 16U;
        for (column = 0; column < 16; ++column) sum += row_weight[column] * workspace->hidden_256[column];
        action[row] = sum;
    }
}


static float pulse_step(G1AssistV4Controller *c, float action, float gate)
{
    float *s=c->pulse;
    float delta=c->filtered_velocity[0]-c->filtered_velocity[1];
    float direction=(delta<-.3f && c->filtered_velocity[0]<-.2f) ? -1.0f :
        (delta>.3f && c->filtered_velocity[1]<-.2f) ? 1.0f : 0.0f;
    s[7]=direction==s[6] ? fminf(s[7]+.01f,.03f) : .01f;
    s[6]=direction;
    int confirmed=s[7]>=.03f-1e-6f;
    int active=s[1]!=0, releasing=s[3]>0;
    if(active && !releasing && confirmed && direction!=s[1]) {
        s[3]=.01f; s[4]=fabsf(c->previous[0]);
    }
    releasing=s[3]>0;
    if(!active && confirmed && direction==0) s[5]=0;
    if(!active && confirmed && direction!=0 && direction!=s[5]) {
        s[0]=0; s[1]=direction; s[2]=.5f*(clip(action,-1,1)+1)*10*gate;
        s[5]=direction; s[3]=s[4]=0;
    }
    active=s[1]!=0;
    if(active && !releasing) s[0]+=.01f;
    float phase=clip(s[0]/.4f,0,1), rp=clip(s[3]/.2f,0,1);
    float wave=releasing ? cosf(1.5707963267948966f*rp) : sinf(3.141592653589793f*phase);
    float magnitude=(releasing ? s[4] : s[2])*wave*wave;
    float result=active ? s[1]*magnitude : 0;
    int done=active && ((!releasing && s[0]>=.4f-1e-6f) || (releasing && s[3]>=.2f-1e-6f));
    if(done) { result=0; for(int i=0;i<5;++i) s[i]=0; }
    if(releasing && !done) s[3]+=.01f;
    return result;
}

static int finite_pair(const float *x)
{
    return x != NULL && isfinite(x[0]) && isfinite(x[1]);
}
void g1_assist_v4_stop(G1AssistV4Controller *c, float out[2])
{
    if (out != NULL) out[0] = out[1] = 0.0f;
    if (c == NULL) return;
    c->ready = 0U;
    for (size_t i=0; i<8; ++i) c->pulse[i]=0.0f;
    c->previous[0] = c->previous[1] = 0.0f;
    c->filtered_velocity[0] = c->filtered_velocity[1] = 0.0f;
}
int g1_assist_v4_reset(G1AssistV4Controller *c, const float p[2], const float v[2])
{
    if (c == NULL) return -1;
    g1_assist_v4_stop(c, NULL);
    if (!finite_pair(p) || !finite_pair(v)) return -1;
    g1_assist_v4_history_reset(&c->history, p, v);
    c->first = 1U;
    c->ready = 1U;
    return 0;
}
int g1_assist_v4_step(G1AssistV4Controller *c, const float p[2], const float v[2], int enabled, float out[2])
{
    float action[1], speed, phase, state[10], output;
    const float scale[8]={.4f,1,10,.2f,10,1,1,.03f};
    size_t side;
    if (c == NULL || out == NULL) {
        g1_assist_v4_stop(c, out);
        return -1;
    }
    out[0] = out[1] = 0;
    if (!enabled || !c->ready) {
        g1_assist_v4_stop(c, out);
        return 1;
    }
    if (!finite_pair(p) || !finite_pair(v)) {
        g1_assist_v4_stop(c, out);
        return -1;
    }
    if (c->first) g1_assist_v4_history_reset(&c->history, p, v);
    else {
        for (side=0; side<8; ++side) state[side]=c->pulse[side]/scale[side];
        state[8]=c->filtered_velocity[0]; state[9]=c->filtered_velocity[1];
        g1_assist_v4_history_append(&c->history, p, v, c->previous, state);
    }
    c->first = 0U;
    g1_assist_v4_history_build_observation(&c->history, c->observation);
    g1_assist_v4_policy_forward(c->observation, action, &c->workspace);
    if (!isfinite(action[0])) {
        g1_assist_v4_stop(c, out);
        return -1;
    }
    for (side = 0; side < 2; ++side) {
        c->filtered_velocity[side] += (1.0f-expf(-0.01f/0.05f)) * (v[side]-c->filtered_velocity[side]);
    }
    speed = fmaxf(fabsf(c->filtered_velocity[0]), fabsf(c->filtered_velocity[1]));
    phase = clip((speed-0.15f)/0.65f, 0, 1);
    output = pulse_step(c, action[0], phase*phase*(3-2*phase));
    c->previous[0]=output; c->previous[1]=-output;
    out[0]=output; out[1]=-output;
    return 0;
}

